import{z as d,x as p,o,c as A,q as s,j as n,D as e,d as r,s as i,S as E,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"整数溢出漏洞","description":"","frontmatter":{"title":"整数溢出漏洞","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/integer-overflow-bugs.md","filePath":"cs/integer-overflow-bugs.md","lastUpdated":1791413859000}'),B={name:"cs/integer-overflow-bugs.md"};function c(C,a,m,h,u,f){const t=p("Mermaid");return o(),A("div",null,[a[2]||(a[2]=s('<h1 id="整数溢出漏洞" tabindex="-1">整数溢出漏洞 <a class="header-anchor" href="#整数溢出漏洞" aria-label="Permalink to &quot;整数溢出漏洞&quot;">​</a></h1><div class="epigraph"><p>长度先用机器整数算，再拿去 `malloc` 和 `memcpy`。绕回零的乘会分到短缓冲再写长数据。这是类型与宽度问题，不是「再加一个 canary」能定义的。</p><footer>—— 据 Brumley, Chiueh 等对整数错误的讨论；CWE-190；对照 ISO C 对无符号绕回</footer></div><p>上一课<a href="/cs/heap-allocator-attacks">分配器</a>假定请求的大小是诚实的。缺口是<strong>算术</strong>：宽类型截断、有符号转无符号、乘法溢出。本课讲检查应在算术层，不给绕过补丁的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>n * size</code> 绕回后分配很小，循环仍按 <code>n</code> 写。缺口是：所有「计数→字节」的边都要饱和或显式检查。语言若提供检查乘法，应默认用。</p><p><span class="marginnote">数字实例：32 位无符号整数的上限是 \\(2^{32}-1\\)。若每个元素 4 字节、<code>n</code> 取 \\(2^{30}\\)，乘积恰是 \\(2^{32}\\)，绕回后等于 0——<code>malloc(0)</code> 拿到极小的合法内存，程序随后却按 10 亿个元素往里写。</span></p><h3 id="有符号与无符号" tabindex="-1">有符号与无符号 <a class="header-anchor" href="#有符号与无符号" aria-label="Permalink to &quot;有符号与无符号&quot;">​</a></h3><p>比较两边类型不同会让「负长度」变成巨大无符号，另一类洞。</p><p><span class="marginnote">术语翻译：「截断」就是把宽类型的数硬塞进窄类型、只保留低位：把 0x10001 塞进 16 位类型只剩 0x0001，数值被悄悄改掉；而「符号转换」则是把 -1 这类负数读成无符号，直接变成约 42 亿。</span></p><p><span class="marginnote">CWE-190/191。本课不写触发某 CVE 的输入。编译器未定义行为对有符号溢出另有坑，点名<a href="/cs/undefined-behavior-opt">未定义行为</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出转换点：乘法、加法、截断、符号。要求 API 用更大类型或饱和。对照：格式化字符串下一课是另一类「解释用户串当格式」。</p>',13)),(o(),n(E,null,{default:e(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUL%5B%22n%20%C3%97%20size%20%E7%BB%95%E5%9B%9E%22%5D%20--%3E%20SMALL%5B%22%E7%9F%AD%E5%88%86%E9%85%8D%22%5D%0A%20%20SMALL%20--%3E%20COPY%5B%22%E4%BB%8D%E6%8C%89%20n%20%E5%86%99%22%5D%0A%20%20CHK%5B%22%E6%A3%80%E6%9F%A5%E6%88%96%E9%A5%B1%E5%92%8C%22%5D%20--%3E%20OK%5B%22%E6%8B%92%E7%BB%9D%E6%88%96%E6%AD%A3%E7%A1%AE%E5%A4%A7%E5%B0%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[r("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"空间安全的输入是长度。长度不可信则分配器与复制都不可信。下一课格式化字符串：控制解释器而不是长度。",-1)),a[5]||(a[5]=l("p",null,"检查要放在「算出长度」的那几步算术上，而不是等分配完再补救。",-1)),(o(),n(E,null,{default:e(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%20n%20%E4%B8%8E%20elem_size%22%5D%20--%3E%20C1%7B%22n%20%5Cgt%20%E4%B8%8A%E9%99%90%20%C3%B7%20elem_size%20%3F%22%7D%0A%20%20C1%20--%3E%7C%22%E6%98%AF%22%7C%20R%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E9%95%BF%E5%BA%A6%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20C1%20--%3E%7C%22%E5%90%A6%22%7C%20M%5B%22%E6%89%A7%E8%A1%8C%20n%20%C3%97%20elem_size%22%5D%0A%20%20M%20--%3E%20C2%7B%22%E6%9C%89%E6%88%AA%E6%96%AD%E6%88%96%E7%AC%A6%E5%8F%B7%E8%BD%AC%E6%8D%A2%3F%22%7D%0A%20%20C2%20--%3E%7C%22%E6%9C%89%22%7C%20R%0A%20%20C2%20--%3E%7C%22%E6%97%A0%22%7C%20A%5B%22%E6%8C%89%E7%BB%93%E6%9E%9C%E5%88%86%E9%85%8D%E5%B9%B6%E5%A4%8D%E5%88%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：初学者容易以为加个 canary 或事后校验缓冲区就能挡住这类洞；实际上绕回发生在「算出长度」那一刻，等 <code>malloc</code> 收到那个虽错误却「合法」的小值，后续防线已经无从知道真实长度了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给整数溢出 exploit。格式化字符串下一课同样只讲机制与禁用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分配器收到的 size 可能已被绕回。</li><li>计数到字节必须检查宽度。</li><li>符号转换是同类洞。</li><li>下一课格式化字符串。</li><li>出处：CWE-190；ISO C；Brumley et al. 对整数错误的分析。</li></ul>',5))])}const b=d(B,[["render",c]]);export{_ as __pageData,b as default};
